import {CATEGORIES,LABELS} from './engine.js?v=2.5.0';
import {coordinateKey} from './heat-map.js?v=2.5.0';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Number.isFinite(v)?Number(v.toPrecision(5)).toString():'—';
export const applicable={MOSFET:['conduction','body','on','off','recovery'],Diode:['conduction','recovery'],Capacitor:['copper'],Inductor:['copper','core']};
const palette=['#c6f278','#82bfff','#c6a0f6','#f6b56d','#f49cac','#79d8c1','#a6b6c8'];
export const sameCoordinate=(a,b)=>Number.isFinite(a)&&Number.isFinite(b)&&coordinateKey(a)===coordinateKey(b);
export function filterRange(rows,filters={}){return rows.filter(r=>['vin','vout','outputPower'].every(k=>filters[k]==null||filters[k]==='all'||sameCoordinate(r[k],Number(filters[k]))));}
export function coordinateOptions(rows,key){return [...new Map(rows.filter(r=>Number.isFinite(r[key])).map(r=>[coordinateKey(r[key]),r[key]])).values()].sort((a,b)=>a-b);}
export function rangeSummary(rows,ranking){return ranking.map(rank=>{const rs=rows.filter(r=>r.combination===rank.combination),valid=rs.filter(r=>r.valid),complete=rs.length>0&&rs.every(r=>r.valid),mean=k=>valid.length?valid.reduce((s,r)=>s+r[k],0)/valid.length:null;return {...rank,count:rs.length,validCount:valid.length,complete,meanEfficiency:mean('efficiency'),meanLoss:mean('totalLoss'),worstEfficiency:valid.length?Math.min(...valid.map(r=>r.efficiency)):null,maxTemperature:valid.length?Math.max(...valid.flatMap(r=>r.devices.map(d=>d.temperature)).filter(Number.isFinite)):null};}).filter(r=>r.count);}
export function meanResult(rows,combination){const rs=rows.filter(r=>r.combination===combination);if(!rs.length)return null;const valid=rs.every(r=>r.valid),base=rs[0];if(!valid)return {...base,valid:false,totalLoss:null,categories:null};return {...base,valid:true,totalLoss:rs.reduce((s,r)=>s+r.totalLoss,0)/rs.length,categories:Object.fromEntries(CATEGORIES.map(k=>[k,rs.reduce((s,r)=>s+r.categories[k],0)/rs.length])),devices:base.devices.map(d=>({...d,total:rs.reduce((s,r)=>s+r.devices.find(v=>v.instanceId===d.instanceId).total,0)/rs.length,categories:Object.fromEntries(CATEGORIES.map(k=>[k,rs.reduce((s,r)=>s+r.devices.find(v=>v.instanceId===d.instanceId).categories[k],0)/rs.length]))}))};}
function keysFor(project,ids){return CATEGORIES.filter(k=>project.instances.some(i=>(!ids||ids.includes(i.id))&&(applicable[i.type]||[]).includes(k)));}
function label(k,project,ids){const inst=project.instances.filter(i=>!ids||ids.includes(i.id));if(inst.length===1&&k==='copper')return inst[0].type==='Capacitor'?'ESR loss':'Winding / copper loss';return LABELS[k];}
function enabled(row,key,project){return row.devices.some(d=>project.instances.find(i=>i.id===d.instanceId)?.candidates.find(c=>c.id===d.candidateId)?.enabled.includes(key));}
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
export function pairedLossCharts(rows,project,unit='W'){
 if(!rows.length)return '<p>No results match these filters.</p>';
 const valid=rows.filter(r=>r.valid),max=unit==='%'?100:Math.max(1e-12,...valid.map(r=>r.totalLoss)),keys=keysFor(project);
 const valueTable=table(['Combination','Component / contribution','Loss [W]','Share of total'],rows.flatMap(r=>!r.valid?[`<tr><td>${r.combination}</td><td colspan="3">Incomplete — unavailable</td></tr>`]:r.devices.flatMap(d=>{const inst=project.instances.find(i=>i.id===d.instanceId),candidate=inst?.candidates.find(c=>c.id===d.candidateId);return [`<tr><td>${r.combination}</td><td><b>${e(d.instanceName)}</b></td><td>${n(d.total)}</td><td>${n(r.totalLoss?100*d.total/r.totalLoss:0)}%</td></tr>`,...(applicable[inst?.type]||[]).map(k=>`<tr><td>${r.combination}</td><td>${e(d.instanceName)} · ${e(label(k,project,[d.instanceId]))}</td><td>${candidate?.enabled.includes(k)?n(d.categories[k]):'Excluded'}</td><td>${candidate?.enabled.includes(k)?n(r.totalLoss?100*d.categories[k]/r.totalLoss:0)+'%':'—'}</td></tr>`)];})));
 return `<div class="combined-loss-chart" role="group" aria-label="Losses by contribution and component"><h3>Combined component and contribution breakdown</h3>${rows.map(r=>{
  if(!r.valid)return `<div class="result-stack-row"><span>Combination ${r.combination}</span><span class="result-unavailable">Incomplete — unavailable</span></div>`;
  const total=r.totalLoss;
  return `<div class="result-stack-row"><span>Combination ${r.combination}</span><div class="result-stack-space"><div class="result-joint-stack" style="width:${unit==='%'?(total>0?100:0):100*total/max}%">${project.instances.map(inst=>{
   const d=r.devices.find(d=>d.instanceId===inst.id);if(!d||!(d.total>0))return '';
   const attributes=`data-explore-component="${e(inst.id)}" data-explore-combination="${r.combination}" data-explore-wave="${e(r.waveformId)}"`,share=100*d.total/total,info=`${d.instanceName}: ${n(d.total)} W · ${n(share)}% of total`,name=d.instanceName.split(' · ')[0];
   return `<div class="result-component-block" data-component-total="${d.total}" style="width:${share}%"><div class="result-contributions" aria-label="Losses by contribution · ${e(d.instanceName)}">${(applicable[inst.type]||[]).filter(k=>d.categories[k]>0).map(k=>{
    const text=`${d.instanceName} · ${label(k,project,[inst.id])}: ${n(d.categories[k])} W · ${n(100*d.categories[k]/total)}% of total`;
    return `<button type="button" class="result-segment" ${attributes} data-explore-category="${k}" data-result-value="${e(text)}" aria-label="${e(text)}" title="${e(text)}" style="width:${100*d.categories[k]/d.total}%;background:${palette[CATEGORIES.indexOf(k)]}">${100*d.categories[k]/total>=15?n(d.categories[k]):''}</button>`;
   }).join('')}</div><button type="button" class="result-component-label" ${attributes} data-result-value="${e(info)}" aria-label="Inspect ${e(info)}" title="${e(info)}">${e(name)}</button></div>`;
  }).join('')}</div>${total===0?'<span class="caption">0 W included losses</span>':''}</div><span>${n(unit==='%'?(total>0?100:0):total)} ${unit}</span></div>`;
 }).join('')}<div class="result-stack-row result-loss-axis" aria-hidden="true"><span></span><div class="result-loss-ticks"><span>0</span><span>${n(max/2)}</span><span>${n(max)} ${unit}</span></div><span></span></div><p class="caption">${unit==='%'?'Each bar = 100% of included losses':'Common scale · included losses [W]'} · coloured contributions above, aligned component shares below.</p><div class="result-legend">${keys.map(k=>`<span><i style="background:${palette[CATEGORIES.indexOf(k)]}"></i>${e(LABELS[k])}${rows.some(r=>enabled(r,k,project))?'':' · Excluded'}</span>`).join('')}</div><p class="caption result-chart-readout" aria-live="polite">Hover or focus for watts and shares. Select a component or contribution to inspect that component.</p><details><summary>Show contribution and component values</summary>${valueTable}</details></div>`;
}
export function bindResultTooltips(root,tip){if(!tip)return;root.querySelectorAll('[data-result-value]').forEach(el=>{
 el.removeAttribute?.('title');el.setAttribute?.('aria-describedby','resultHoverTooltip');
 const hide=()=>{tip.hidden=true;};
 const show=event=>{tip.textContent=el.dataset.resultValue;tip.hidden=false;const rect=el.getBoundingClientRect(),w=tip.getBoundingClientRect().width||240,h=tip.getBoundingClientRect().height||50,vw=globalThis.innerWidth||1024,vh=globalThis.innerHeight||768,x=Number.isFinite(event?.clientX)?event.clientX:rect.left+rect.width/2,y=Number.isFinite(event?.clientY)?event.clientY:rect.bottom;tip.style.left=Math.max(8,Math.min(x+12,vw-w-8))+'px';tip.style.top=Math.max(8,Math.min(y+12,vh-h-8))+'px';};
 el.addEventListener('pointerenter',show);el.addEventListener('pointermove',show);el.addEventListener('pointerleave',hide);el.addEventListener('focus',show);el.addEventListener('blur',hide);el.addEventListener('click',hide);
 });}
export function groupedLossCharts(rows,project,state){const groups=new Map();for(const r of rows){const key=coordinateKey(r.vin)+':'+coordinateKey(r.vout);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}return [...groups.values()].map((rs,j)=>{const combos=[...new Set(rs.map(r=>r.combination))],powers=coordinateOptions(rs,'outputPower');return `<details class="result-voltage-group" ${j===0?'open':''}><summary>Vin ${n(rs[0].vin)} V · Vout ${n(rs[0].vout)} V · ${powers.length} power points</summary>${state.breakdown==='points'?powers.map(p=>`<h3>Pout ${n(p)} W</h3>${pairedLossCharts(rs.filter(r=>sameCoordinate(r.outputPower,p)),project,state.unit)}`).join(''):`<p class="caption">Mean across the same ${powers.length} sampled power points · equal weighting</p>${pairedLossCharts(combos.map(id=>meanResult(rs,id)),project,state.unit)}`}</details>`;}).join('')||'<p>No operating points match these filters.</p>';}
export function componentLossView(row,project,instanceId){const d=row?.devices.find(d=>d.instanceId===instanceId),inst=project.instances.find(i=>i.id===instanceId);if(!d||!inst)return '<p>Select a component.</p>';const c=inst.candidates.find(c=>c.id===d.candidateId),keys=keysFor(project,[inst.id]);return `<h3>${e(d.instanceName)} / ${e(d.part)}</h3><p>${e(inst.type)} · selected component only · ${d.valid?n(d.total)+' W':e(d.error||'Incomplete')} · ${n(d.temperature)} °C</p>${d.valid?keys.map(k=>`<div class="barrow"><span>${e(label(k,project,[inst.id]))}</span><div class="track"><div class="fill" style="width:${c.enabled.includes(k)&&d.total>0?100*d.categories[k]/d.total:0}%;background:${palette[CATEGORIES.indexOf(k)]}"></div></div><span>${c.enabled.includes(k)?n(d.categories[k])+' W':'Excluded'}</span></div>`).join(''):'<p>Losses unavailable. Recorded queries and waveforms remain in Debug & interpolation.</p>'}<button class="ghost" data-component-debug="${e(inst.id)}">Open component in query debugger ↗</button>`;}
export function explorerFilter(rows,key,value,id,all=true){const opts=coordinateOptions(rows,key);return `<label>${key==='outputPower'?'Pout [W]':key==='vin'?'Vin [V]':'Vout [V]'}<select id="${id}">${all?'<option value="all">All</option>':''}${opts.map(v=>`<option value="${coordinateKey(v)}" ${value!=='all'&&sameCoordinate(v,Number(value))?'selected':''}>${n(v)}</option>`).join('')}</select></label>`;}
export function rangeTable(summaries){const eligible=summaries.filter(s=>s.complete),best=[...eligible].sort((a,b)=>b.meanEfficiency-a.meanEfficiency)[0];return `<p class="caption">Equal weighting of the selected sampled operating points. Incomplete alternatives remain visible; they are not eligible for a best label.</p>${table(['Combination / parts','Mean η [%]','Worst η [%]','Mean loss [W]','Peak T [°C]','Complete points'],summaries.map(s=>`<tr><td><button class="ghost" data-combination="${s.combination}">#${s.combination}${best?.combination===s.combination?' · Best mean efficiency':''}</button><br>${e(s.parts)}</td><td>${n(s.meanEfficiency)}</td><td>${n(s.worstEfficiency)}</td><td>${n(s.meanLoss)}</td><td>${n(s.maxTemperature)}</td><td>${s.validCount}/${s.count}${s.complete?'':' · Incomplete; averages use valid points only'}</td></tr>`))}`;}
export function rangePerformance(rows,graph,metric='efficiency'){const keys={efficiency:['efficiency','Efficiency [%]'],loss:['totalLoss','Included losses [W]'],temperature:['temperature','Peak component temperature [°C]']},[key,label]=keys[metric]||keys.efficiency,groups=new Map();for(const r of rows.filter(r=>r.valid)){const name=`Combination ${r.combination} · Vin ${n(r.vin)} V / Vout ${n(r.vout)} V`;if(!groups.has(name))groups.set(name,[]);groups.get(name).push(r);}return graph([...groups].map(([name,rs],j)=>({name,color:palette[(rs[0].combination-1)%palette.length],points:rs.sort((a,b)=>a.outputPower-b.outputPower).map(r=>[r.outputPower,key==='temperature'?Math.max(...r.devices.map(d=>d.temperature)):r[key]])})),{xLabel:'Output power [W]',yLabel:label});}
// Display-only projection; the original converter result and efficiency are retained.
export function componentScope(rows,project,ids=null){const selected=ids===null?project.instances.map(i=>i.id):ids.filter(id=>project.instances.some(i=>i.id===id));if(!selected.length)return [];return rows.map(r=>{const devices=r.devices.filter(d=>selected.includes(d.instanceId)),complete=r.valid&&devices.every(d=>d.valid),categories=Object.fromEntries(CATEGORIES.map(k=>[k,complete?devices.reduce((v,d)=>v+(d.categories?.[k]||0),0):null]));return {...r,devices,converterTotalLoss:r.converterTotalLoss??r.totalLoss,totalLoss:complete?devices.reduce((v,d)=>v+d.total,0):null,categories,valid:complete};});}
export function resultFilterControls(project,ranking,components=null,combinations=null){const ids=components??project.instances.map(i=>i.id),combos=combinations??ranking.map(r=>r.combination);return `<section class="panel result-filters"><h2>Comparison filters</h2><div class="grid2"><div><h3>Components (${ids.length}/${project.instances.length})</h3><div class="toolbar"><button class="ghost small" data-filter-action="components-all">Select all</button><button class="ghost small" data-filter-action="components-none">Clear</button></div>${project.instances.map(i=>`<label class="check"><input type="checkbox" data-result-component="${e(i.id)}" ${ids.includes(i.id)?'checked':''}>${e(i.name)} · ${e(i.type)}</label>`).join('')}</div><div><details><summary>Alternatives / combinations (${combos.length}/${ranking.length})</summary><div class="toolbar"><button class="ghost small" data-filter-action="alternatives-all">Select all</button><button class="ghost small" data-filter-action="alternatives-none">Clear</button></div>${ranking.map(r=>`<label class="check"><input type="checkbox" data-range-combination="${r.combination}" ${combos.includes(r.combination)?'checked':''}>#${r.combination} · ${e(r.parts)}</label>`).join('')}</details></div></div><p class="caption">${ids.length?e(project.instances.filter(i=>ids.includes(i.id)).map(i=>i.name).join(' + ')):'No components selected'} · ${combos.length} combinations. Loss subtotals and shares include only these components. Converter efficiency remains based on all enabled component losses. Filters change the display without rerunning; CSV, JSON and report scopes are selected separately.</p></section>`;}
